svg.script:
(function () {
  function init() {
    var doc = document;
    var svg = doc.getElementById('svg1') || doc.querySelector('svg');
    if (!svg) return;

    var tip = doc.getElementById('site-tooltip');
    var tooltipRect = doc.getElementById('tooltip-bg');
    var tooltipShadow = doc.getElementById('tooltip-shadow');
    var tooltipAccent = doc.getElementById('tooltip-accent');
    var siteNameText = doc.getElementById('tooltip-site-name');
    var telemetryText = doc.getElementById('tooltip-telemetry');
    var assetText = doc.getElementById('tooltip-asset');
    var hoverTip = doc.getElementById('hover-tooltip');
    var hoverRect = doc.getElementById('hover-tooltip-bg');
    var hoverName = doc.getElementById('hover-tooltip-site-name');
    var selectedIndicator = doc.getElementById('selected-site-indicator');
    var statusLegend = doc.getElementById('status-legend');
    var resetArea = doc.getElementById('map-reset-click-area');
    var siteSelector = '.site-marker, .Site, circle[id^="site-"], ellipse[id^="site-"], rect[id^="site-"], path[id^="site-"], g[id^="site-"]';

    function inLegend(t) { return !!(statusLegend && t && (t === statusLegend || statusLegend.contains(t))); }
    function findSite(t) {
      if (inLegend(t) || !t || !t.closest) return null;
      var el=t.closest(siteSelector);
      if (!el || el===tip || el===hoverTip || (tip&&tip.contains(el)) || (hoverTip&&hoverTip.contains(el))) return null;
      return el;
    }
    function makeClickable() {
      doc.querySelectorAll(siteSelector).forEach(function(s){
        if (s===tip || s===hoverTip || (tip&&tip.contains(s)) || (hoverTip&&hoverTip.contains(s))) return;
        s.style.cursor='pointer'; s.style.pointerEvents='all'; s.setAttribute('tabindex','0');
        if (!s.getAttribute('role')) s.setAttribute('role','button');
        s.setAttribute('Interconnect','Selected');
      });
    }
    makeClickable();
    if (tip) tip.style.pointerEvents='none';
    if (hoverTip) hoverTip.style.pointerEvents='none';

    function svgPoint(evt) {
      var p=svg.createSVGPoint(); p.x=evt.clientX||0; p.y=evt.clientY||0;
      var ctm=svg.getScreenCTM(); return ctm?p.matrixTransform(ctm.inverse()):p;
    }
    function anchor(evt,el) {
      if (evt && typeof evt.clientX==='number') return svgPoint(evt);
      var box=el.getBBox(); return {x:box.x+box.width/2,y:box.y+box.height/2};
    }
    function position(group,rect,evt,el) {
      if (!group || !rect) return;
      var p=anchor(evt,el), w=parseFloat(rect.getAttribute('width'))||400, h=parseFloat(rect.getAttribute('height'))||100;
      var vb=svg.viewBox.baseVal, gap=Math.max(vb.width/120,12);
      var x=p.x+gap, y=p.y-h-gap;
      if (x+w>vb.x+vb.width) x=p.x-w-gap;
      if (y<vb.y) y=p.y+gap;
      x=Math.max(vb.x,Math.min(x,vb.x+vb.width-w));
      y=Math.max(vb.y,Math.min(y,vb.y+vb.height-h));
      group.setAttribute('transform','translate('+x+','+y+')');
    }
    function showHover(el,evt) {
      if (!hoverTip || !hoverRect || !hoverName) return;
      var n=el.getAttribute('data-site-name')||el.getAttribute('data-asset-id')||el.id||'Unknown site';
      hoverName.textContent=n;
      var fs=parseFloat(hoverName.getAttribute('font-size'))||40;
      hoverRect.setAttribute('width',Math.max(fs*7,Math.min(fs*22,fs*(2+n.length*.62))));
      hoverTip.setAttribute('visibility','visible'); position(hoverTip,hoverRect,evt,el);
    }
    function hideHover(){ if(hoverTip) hoverTip.setAttribute('visibility','hidden'); }
    function updateSelected(el) {
      if (!selectedIndicator) return;
      ['id','telemetry-id','status','asset-id','site-name'].forEach(function(k){
        var attr=k==='id'?'id':'data-'+k;
        selectedIndicator.setAttribute('data-'+k+'-selected',el.getAttribute(attr)||'');
      });
      var b=el.getBBox(); selectedIndicator.setAttribute('cx',b.x+b.width/2); selectedIndicator.setAttribute('cy',b.y+b.height/2);
      selectedIndicator.setAttribute('r',Math.max(b.width,b.height)/2+10); selectedIndicator.setAttribute('visibility','visible');
    }
    function showPopup(el,evt) {
      if (!tip || !tooltipRect || !siteNameText || !telemetryText || !assetText) return;
      var n=el.getAttribute('data-site-name')||el.id||'Unknown site';
      var t=el.getAttribute('data-telemetry-id')||'N/A';
      var a=el.getAttribute('data-asset-id')||'N/A';
      siteNameText.textContent=n; telemetryText.textContent='Telemetry ID: '+t; assetText.textContent='Asset ID: '+a;
      var fs=parseFloat(siteNameText.getAttribute('font-size'))||40;
      var longest=Math.max(n.length,telemetryText.textContent.length,assetText.textContent.length);
      var w=Math.max(fs*16,Math.min(fs*26,fs*(2+longest*.62)));
      tooltipRect.setAttribute('width',w); if(tooltipShadow) tooltipShadow.setAttribute('width',w);
      if(tooltipAccent) tooltipAccent.setAttribute('height',tooltipRect.getAttribute('height'));
      tip.setAttribute('visibility','visible'); position(tip,tooltipRect,evt,el); updateSelected(el);
    }
    function clearPopup(){ if(tip) tip.setAttribute('visibility','hidden'); if(selectedIndicator) selectedIndicator.setAttribute('visibility','hidden'); }

    svg.addEventListener('pointermove',function(evt){ var s=findSite(evt.target); s?showHover(s,evt):hideHover(); },true);
    svg.addEventListener('pointerleave',hideHover,true);
    svg.addEventListener('click',function(evt){
      if(inLegend(evt.target)){ hideHover(); evt.preventDefault(); evt.stopImmediatePropagation(); return; }
      var s=findSite(evt.target);
      if(s){ showPopup(s,evt); setTimeout(function(){showPopup(s,evt);},0); }
      else { clearPopup(); hideHover(); }
      // Do not stop propagation: Asset Intellect must receive the original click.
    },true);
    svg.addEventListener('keydown',function(evt){ if(evt.key==='Enter'||evt.key===' '){var s=findSite(evt.target);if(s)showPopup(s,evt);} },true);
    if(window.MutationObserver){ new MutationObserver(makeClickable).observe(svg,{childList:true,subtree:true,attributes:true,attributeFilter:['id','class']}); }
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',init); else init();
})();
